import{_ as l,a0 as p,w as s,s as d,ao as i,I as a,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"如何在Linux中安装Go语言 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Linux中安装Go语言 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Linux中安装Go语言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Linux中安装Go语言 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150205 Linux FAQs with Answers--How to install Go language on Linux","title":"如何在Linux中安装Go语言","tag":"201502","desc":""},"relativePath":"201502/20150205 Linux FAQs with Answers--How to install Go language on Linux.md","filePath":"[post].md"}'),g={name:"201502/20150205 Linux FAQs with Answers--How to install Go language on Linux.md"};function u(x,o,m,c,f,T){const t=p("Link");return s(),d("div",null,[o[14]||(o[14]=i(`<h1 id="如何在linux中安装go语言" tabindex="-1">如何在Linux中安装Go语言 <a class="header-anchor" href="#如何在linux中安装go语言" aria-label="Permalink to “如何在Linux中安装Go语言”">​</a></h1><p>Go (也叫 &quot;golang&quot;)是一款由Google最初开发的编程语言。它的诞生有几个设计原则：简单、安全、速度。Go语言发行版拥有各种调试、测试、调优和代码审查工具。如今Go语言和它的工具链在大多数Linux发行版的基础仓库都可用，用默认的包管理器就可以安装。</p><h3 id="在ubuntu、debian-或者-linux-mint上安装go语言" tabindex="-1">在Ubuntu、Debian 或者 Linux Mint上安装Go语言 <a class="header-anchor" href="#在ubuntu、debian-或者-linux-mint上安装go语言" aria-label="Permalink to “在Ubuntu、Debian 或者 Linux Mint上安装Go语言”">​</a></h3><p>下面是在基于Debian的发行版上使用<strong>apt-get</strong>来安装Go语言和它的开发工具。</p><pre><code>$ sudo apt-get install golang
</code></pre><p>检查Go语言的版本来验证安装。</p><pre><code>$ go version
</code></pre><hr><pre><code>go version go1.2.1 linux/amd64
</code></pre><p>根据你的需要，你或许想要使用apt-get安装额外的Go工具。</p><pre><code>$ sudo apt-cache search golang
</code></pre><p><img src="https://farm8.staticflickr.com/7430/15812762183_f094e3bf92_c.jpg" alt=""></p><h3 id="在fedora、centos-rhel中安装go语言" tabindex="-1">在Fedora、CentOS/RHEL中安装Go语言 <a class="header-anchor" href="#在fedora、centos-rhel中安装go语言" aria-label="Permalink to “在Fedora、CentOS/RHEL中安装Go语言”">​</a></h3><p>下面的命令会在基于Red Hat的发行版中安装Go语言和它的工具。</p><pre><code>$ sudo yum install golang
</code></pre><p>检查Go语言的版本来验证安装。</p><pre><code>$ go version 
</code></pre><hr><pre><code>go version go1.3.3 linux/amd64
</code></pre><p>根据你的需要，你或许想要使用yum安装额外的Go工具。</p><pre><code>$ yum search golang 
</code></pre><p><img src="https://farm8.staticflickr.com/7373/16432817805_775010dc18_c.jpg" alt=""></p><h3 id="从官网安装go语言" tabindex="-1">从官网安装Go语言 <a class="header-anchor" href="#从官网安装go语言" aria-label="Permalink to “从官网安装Go语言”">​</a></h3><p>有时发行版中的go语言版本并不是最新的。为了避免这种情况，你可以从官网安装最新的Go语言。下面是步骤。</p>`,24)),a("p",null,[o[1]||(o[1]=e("进入Go语言的",-1)),n(t,{href:"https://golang.org/dl/"},{default:r(()=>[...o[0]||(o[0]=[e("官方源码",-1)])]),_:1}),o[2]||(o[2]=e("，并下载预编译二进制代码。",-1))]),o[15]||(o[15]=i(`<p><strong>对于64位Linux:</strong></p><pre><code>$ wget https://storage.googleapis.com/golang/go1.4.1.linux-amd64.tar.gz
</code></pre><p><strong>对于32位Linux:</strong></p><pre><code>$ wget https://storage.googleapis.com/golang/go1.4.1.linux-386.tar.gz
</code></pre><p><strong>在/usr/local下安装程序</strong></p><pre><code>$ sudo tar -xzf go1.4.1.linux-xxx.tar.gz -C /usr/local
</code></pre><p>在/etc/profile中添加系统范围的PATH环境变量。</p><pre><code>$ sudo vi /etc/profile 
</code></pre><hr><pre><code>export PATH=$PATH:/usr/local/go/bin
</code></pre><p>如果你在/usr/local之外的自定义位置中安装了Go，你同样需要设置GOROOT环境变量来指向自定义的安装位置。</p><pre><code>$ sudo vi /etc/profile
</code></pre><hr><pre><code>export GOROOT=/path/to/custom/location
</code></pre><p>检查Go语言的版本</p><pre><code>$ go version
</code></pre><hr><pre><code>go version go1.4.1 linux/amd64
</code></pre><hr>`,19)),a("p",null,[o[4]||(o[4]=e("via: ",-1)),n(t,{href:"http://ask.xmodulo.com/install-go-language-linux.html"},{default:r(()=>[...o[3]||(o[3]=[e("http://ask.xmodulo.com/install-go-language-linux.html",-1)])]),_:1})]),a("p",null,[o[7]||(o[7]=e("译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:r(()=>[...o[5]||(o[5]=[e("geekpi",-1)])]),_:1}),o[8]||(o[8]=e(" 校对：",-1)),n(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...o[6]||(o[6]=[e("Caroline",-1)])]),_:1})]),a("p",null,[o[11]||(o[11]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[9]||(o[9]=[e("LCTT",-1)])]),_:1}),o[12]||(o[12]=e(" 原创翻译，",-1)),n(t,{href:"http://linux.cn/"},{default:r(()=>[...o[10]||(o[10]=[e("Linux中国",-1)])]),_:1}),o[13]||(o[13]=e(" 荣誉推出",-1))])])}const _=l(g,[["render",u]]);export{L as __pageData,_ as default};
